import java.io.*;import java.nio.file.*;
public class FileCompare{public static void main(String[]a)throws Exception{if(a.length<2||a[0].equals("--help")){System.out.println("Usage: file-compare FILE1 FILE2");System.exit(a.length<2?2:0);}Path p=Path.of(a[0]),q=Path.of(a[1]);long s1=Files.size(p),s2=Files.size(q),off=0;boolean eq=true;try(InputStream x=Files.newInputStream(p);InputStream y=Files.newInputStream(q)){byte[]b1=new byte[65536],b2=new byte[65536];outer:while(true){int n1=x.read(b1),n2=y.read(b2);if(n1!=n2){eq=false;break;}if(n1<0)break;for(int i=0;i<n1;i++,off++)if(b1[i]!=b2[i]){eq=false;break outer;}}}System.out.println("equal="+eq);System.out.println("size1="+s1);System.out.println("size2="+s2);if(!eq)System.out.println("first_difference_offset="+off);System.exit(eq?0:1);}}
